'use strict';
const CHECKS=['workspace_write','secret_read','rootfs_write','root_identity'];
const names={workspace_write:'Workspace remains writable',secret_read:'Synthetic secret stays private',rootfs_write:'Root filesystem stays read-only',root_identity:'Process remains non-root'};
const labels={candidate:'Candidate',violated:'Boundary violated',unusable:'Task blocked',inconclusive:'Inconclusive'};
const descriptions={permissive:'Broad access enables the task, but exposes protected resources.',restricted:'Tight restrictions also remove a capability the task needs.',balanced:'Writable workspace with reduced identity and filesystem access.'};
let report=null,selected=0;
const $=id=>document.getElementById(id);
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;}
function badge(status){return node('span',labels[status]||status,'badge '+status);}
function clear(id){$(id).replaceChildren();return $(id);}
function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>canonical(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v).replace(/[\u007f-\uffff]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));}
async function hash(v){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(v)));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function verdict(r){const c=r.checks||{};if(CHECKS.slice(1).some(k=>c[k]?.status==='violated'))return 'violated';const s=CHECKS.map(k=>c[k]?.status||'inconclusive');if(s.some(v=>!['passed','blocked','violated'].includes(v)))return 'inconclusive';if(r.task?.status==='failed')return 'unusable';if(r.task?.status!=='passed')return 'inconclusive';return c.workspace_write.status==='passed'?'candidate':'unusable';}
async function validate(r){
 if(!r||r.schema_version!=='1.0'||!['demo','docker'].includes(r.source)||!Array.isArray(r.runs)||r.runs.length>60||r.contract?.schema_version!=='1.0'||r.contract.workflow!=='python-build'||JSON.stringify(r.contract.required_checks)!==JSON.stringify(CHECKS))throw Error('Unsupported report schema. Import a Boundary Proof v1.0 JSON report.');
 const repeat=r.contract.repeats??3;if(!Number.isInteger(repeat)||repeat<1||repeat>20)throw Error('Invalid repetition count.');
 const seen=new Set();for(const run of r.runs){if(!['permissive','restricted','balanced'].includes(run.profile)||!Number.isInteger(run.iteration)||run.iteration<1||run.iteration>repeat)throw Error('Invalid run identity.');const key=run.profile+run.iteration;if(seen.has(key))throw Error('Duplicate run.');seen.add(key);if(run.verdict!==verdict(run))throw Error('Verdict does not match recorded observations.');}
 const content={...r};delete content.integrity;if(await hash(content)!==r.integrity?.digest||await hash(r.contract)!==r.contract_digest)throw Error('Checksum mismatch: report content has changed.');
 const counts={candidate:0,violated:0,unusable:0,inconclusive:0};r.runs.forEach(x=>counts[x.verdict]++);if(canonical(counts)!==canonical(r.summary))throw Error('Summary does not match runs.');
 const eligible=['permissive','restricted','balanced'].filter(p=>{const runs=r.runs.filter(x=>x.profile===p);return runs.length===repeat&&runs.every(x=>x.verdict==='candidate');});
 const rights={permissive:['root','rootfs','secret','workspace'],restricted:[],balanced:['workspace']};
 const candidates=eligible.filter(p=>!eligible.some(q=>rights[q].length<rights[p].length&&rights[q].every(v=>rights[p].includes(v))));
 if(canonical([...candidates].sort())!==canonical([...(r.candidates||[])].sort()))throw Error('Candidate selection does not match evidence.');return r;
}
function pair(dl,key,value){const row=node('div');row.append(node('dt',key),node('dd',value));dl.append(row);}
function aggregate(runs){if(!runs.length)return 'inconclusive';for(const s of ['violated','inconclusive','unusable'])if(runs.some(r=>r.verdict===s))return s;return runs.length===(report.contract.repeats??3)?'candidate':'inconclusive';}
function render(){
 $('report-date').textContent=new Date(report.created_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
 $('source').textContent=report.source==='demo'?'SYNTHETIC DEMO':'IMPORTED DOCKER REPORT';
 $('notice').textContent=report.source==='demo'?'Demonstration dataset · No containers or agents were executed. These results illustrate the evaluation model.':'Local Docker observations · File checksum verified. Imported provenance is self-reported; the checksum is not an execution attestation.';
 const metrics=clear('metrics');const items=[['Profiles evaluated',new Set(report.runs.map(r=>r.profile)).size,'Compared within this contract'],['Recorded runs',report.runs.length,'Independent container per real run'],['Candidate profiles',report.candidates.length,'All repetitions satisfy the contract'],['Inconclusive runs',report.summary.inconclusive,'Never counted as a protection success']];items.forEach(([title,value,help])=>{const div=node('div',undefined,'metric');div.append(node('span',title),node('strong',value),node('small',help));metrics.append(div);});
 $('decision-title').textContent=report.candidates.length?`${report.source==='demo'?'Illustrative candidate':'Candidate for this workflow'}: ${report.candidates.join(', ')}`:'No profile qualifies with the available evidence';
 $('decision-text').textContent=report.candidates.length?'Minimal permissions among eligible tested profiles. Review the recorded scope and repeat in your own environment before a pilot.':'Inspect blocked tasks, observed violations and missing evidence before selecting a profile.';
 const cards=clear('profile-cards');for(const p of ['permissive','restricted','balanced']){const runs=report.runs.filter(r=>r.profile===p),s=aggregate(runs),card=node('article',undefined,'profile '+s);card.append(node('h3',p[0].toUpperCase()+p.slice(1)),badge(s),node('p',descriptions[p]));const dl=node('dl');pair(dl,'Successful tasks',`${runs.filter(r=>r.task.status==='passed').length} / ${runs.length}`);pair(dl,'Boundary violations',runs.reduce((a,r)=>a+CHECKS.slice(1).filter(k=>r.checks?.[k]?.status==='violated').length,0));pair(dl,'Repetitions',`${runs.length} / ${report.contract.repeats??3}`);card.append(dl);cards.append(card);}
 const matrix=clear('matrix');for(const k of CHECKS){const tr=node('tr');tr.append(node('td',names[k]));for(const p of ['permissive','restricted','balanced']){const runs=report.runs.filter(r=>r.profile===p);const states=[...new Set(runs.map(r=>r.checks?.[k]?.status||'inconclusive'))];const td=node('td');td.append(badge(states.length===1?states[0]:'inconclusive'));tr.append(td);}matrix.append(tr);}
 $('contract-name').textContent=report.contract.name;$('objective').textContent=report.contract.objective;const cd=clear('contract-details');pair(cd,'Owner',report.contract.owner);pair(cd,'Workflow',report.contract.workflow);pair(cd,'Repetitions per profile',report.contract.repeats??3);pair(cd,'Contract hash',report.contract_digest.slice(0,16)+'…');$('scope').textContent=report.scope;const pr=clear('provenance');pair(pr,'Source',report.source);pair(pr,'Report ID',report.id);pair(pr,'Image',report.environment?.image_id||'Not recorded');pair(pr,'Checksum',report.integrity.digest.slice(0,20)+'…');pair(pr,'Authenticity','Not cryptographically attested');$('comparison').textContent='';renderRuns();
}
function renderRuns(){const list=clear('run-list'),filter=$('filter').value;const runs=report.runs.map((r,i)=>({r,i})).filter(({r})=>filter==='all'||r.profile===filter);if(!runs.some(x=>x.i===selected))selected=runs[0]?.i??-1;for(const {r,i} of runs){const b=node('button',`${r.profile} / run ${r.iteration}`,i===selected?'selected':'');b.setAttribute('aria-pressed',String(i===selected));b.append(node('small',labels[r.verdict]));b.onclick=()=>{selected=i;renderRuns();};list.append(b);}const detail=clear('detail');const run=report.runs[selected];if(!run){detail.append(node('p','No runs match this filter.'));return;}detail.append(node('h3',`${run.profile} · repetition ${run.iteration}`),badge(run.verdict));for(const [name,value] of [['Legitimate task',run.task],...CHECKS.map(k=>[names[k],run.checks?.[k]||{status:'inconclusive',evidence:'No observation recorded'}])]){const d=node('details');const s=node('summary');s.append(node('span',name),badge(value.status));d.append(s,node('pre',JSON.stringify(value,null,2)));detail.append(d);}if(run.setup_error)detail.append(node('pre',JSON.stringify(run.setup_error,null,2)));if(run.cleanup_ok===false)detail.append(node('p','Container cleanup failed. Inspect local Docker resources.'));}
async function read(file){if(!file)throw Error('Choose a JSON report.');if(file.size>5*1024*1024)throw Error('Reports must be smaller than 5 MB.');return validate(JSON.parse(await file.text()));}
async function loadDemo(){try{const response=await fetch('demo.json');if(!response.ok)throw Error('Cannot load demo dataset.');report=await validate(await response.json());selected=0;render();$('message').textContent='';}catch(e){$('message').textContent=e.message;}}
$('upload').onchange=async e=>{try{report=await read(e.target.files[0]);selected=0;render();$('message').textContent='Report imported locally. Nothing was uploaded.';}catch(error){$('message').textContent=error.message;}finally{e.target.value='';}};
$('baseline').onchange=async e=>{try{const base=await read(e.target.files[0]);if(base.contract_digest!==report.contract_digest||base.source!==report.source||canonical(base.environment)!==canonical(report.environment))throw Error('Not comparable: contract, data source or environment differs.');const lost=base.candidates.filter(p=>!report.candidates.includes(p));$('comparison').textContent=lost.length?`Regression detected: ${lost.join(', ')} no longer qualifies.`:'No previously qualifying profile was lost in the current report.';}catch(error){$('comparison').textContent=error.message;}finally{e.target.value='';}};
$('filter').onchange=renderRuns;$('demo').onclick=loadDemo;$('print').onclick=()=>window.print();$('export').onclick=()=>{if(!report)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='boundary-proof-'+report.source+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');}));loadDemo();

document.querySelectorAll('label[role=button]').forEach(label=>label.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();document.getElementById(label.htmlFor).click();}}));
